    partial = [k for k, v in inj.items() if v.get("R") == 1]
    paralysed = [k for k, v in scored.items() if v.get("T") == 0 and v.get("R", 2) == 2]
    unilateral = [k for k, v in scored.items() if v.get("E") == 0]

    def rate(hits, pool):
        return f"{len(hits)}/{len(pool)}" + (f" ({100*len(hits)//len(pool)}%)" if pool else "")

